--
-- Table structure for table `Merchants`
--

DROP TABLE IF EXISTS `Merchants`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Merchants` (
  `id` int NOT NULL AUTO_INCREMENT,
  `merchantId` varchar(45) NOT NULL,
  `name` varchar(45) NOT NULL,
  `logo` longblob,
  `status` enum('REGISTER','PENDING','ACTIVE','INACTIVE','APPROVED','TEMP_BLOCK') NOT NULL DEFAULT 'PENDING',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL,
  `created_by` varchar(45) DEFAULT NULL,
  `updated_by` varchar(45) DEFAULT NULL,
  `settlement_currency` varchar(45) DEFAULT NULL,
  `mobileNum` varchar(45) NOT NULL,
  `emailId` varchar(45) NOT NULL,
  `address` varchar(45) DEFAULT NULL,
  `country` varchar(45) DEFAULT NULL,
  `package_id` int DEFAULT NULL,
  `account_num` varchar(45) DEFAULT NULL,
  `account_ifsc_code` varchar(45) DEFAULT NULL,
  `bank_name` varchar(45) DEFAULT NULL,
  `bussiness_type` varchar(45) DEFAULT NULL,
  `capital` int DEFAULT NULL,
  `account_swift_code` varchar(45) DEFAULT NULL,
  `ip_addr` varchar(45) DEFAULT NULL,
  `id_proof_doc` longblob,
  `address_proof_doc` longblob,
  `id_proof_num` varchar(45) DEFAULT NULL,
  `address_proof_num` varchar(45) DEFAULT NULL,
  `business_name` varchar(45) DEFAULT NULL,
  `pan` varchar(45) DEFAULT NULL,
  `remarks` varchar(45) DEFAULT NULL,
  `api_key` text,
  PRIMARY KEY (`id`),
  UNIQUE KEY `merchantId_UNIQUE` (`merchantId`),
  KEY `fk_Merchants_currency1_idx` (`settlement_currency`),
  CONSTRAINT `fk_Merchants_currency1` FOREIGN KEY (`settlement_currency`) REFERENCES `Currency` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=40 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
